VECS={1:(-1,2),2:(0,-4),3:(3,0),6:(-6,0)}

def f(I):
    H,W=len(I),len(I[0]); O=[r[:] for r in I]
    pts=[(i,j,I[i][j]) for i in range(H) for j in range(W) if I[i][j]!=0]
    # targets & axes
    segs=[]
    for (i,j,c) in pts:
        di,dj=VECS[c]; ax='v' if abs(di)>=abs(dj) else 'h'
        L=max(abs(di),abs(dj))
        if ax=='v': s=(1 if di>0 else -1,0)
        else: s=(0,1 if dj>0 else -1)
        segs.append((i,j,s,L,c))
    occ={}
    for (i,j,sx,sy,L,c) in segs:
        for k in range(1,L):
            p,q=i+sx*k,j+sy*k
            occ.setdefault(p,q,[]).append((c,sx,sy,i,j))
    # crossing resolution: paint beams; a beam cell claimed by >=2 -> crossing
    RES={}
    for (p,q),claims in occ.items():
        if len(claims)>=2: RES[p,q]='X'
    def paint(seg,skip=None):
        i,j,sx,sy,L,c=seg
        for k in range(1,L):
            p,q=i+sx*k,j+sy*k
            if (p,q) in skip: return
            v=RES.get(p,q)
            if v=='X':
                O[p][q]=4; return
            O[p][q]=5
    # first pass: record claims without painting (originals excluded since k starts at1 and originals not in occ)
    claims_by_seg={}
    for seg in segs:
        claims_by_seg[seg]=[p for (p,_),(sx,sy,i,j) in [(p,0)] for p in [0]] # dummy
    # simpler: compute final grid: start from O, paint segments skipping crossing cells, paint crossings as 4, beams stop AT crossing
    # crossings erase subsequent cells of crossed beams: mark
    erased=set()
    for (p,q) in occ:
        if RES[p,q]=='X':
            for (c,sx,sy,i,j) in occ[p,q]:
                for k in range(p,q): pass
                # clear remainder of this beam beyond p,q
                k=1
                while True:
                    np_,nq=i+sx*k,j+sy*k
                    if np_==p and nq==q: break
                    if np_>H or np_<0 or np_>W or np_<0: break
                    erased.add((np_,nq))
                    k+=1
    for seg in segs:
        i,j,sx,sy,L,c=seg
        for k in range(1,L):
            p,q=i+sx*k,j+sy*k
            if (p,q) in erased: continue
            if RES.get(p,q)=='X': O[p][q]=4; break
            O[p][q]=5
    # place copies
    for (i,j,c) in pts:
        di,dj=VECS[c]
        ni,nj=i+di,j+dj
        if 0<=ni<H and 0<=nj<W and I[ni][nj]==0: O[ni][nj]=c
    return O

