VECS={1:(-1,2),2:(0,-4),3:(3,0),6:(-6,0)}

def f(I):
    H,W=len(I),len(I[0]); O=[r[:] for r in I]
    pts=[(i,j,I[i][j]) for i in range(H) for j in range(W) if I[i][j]!=0]
    segs=[]
    for (i,j,c) in pts:
        di,dj=VECS[c]; ax='v' if abs(di)>=abs(dj) else 'h'
        L=max(abs(di),abs(dj))
        sx,sy=(1 if dj>0 else -1, 0) if ax=='h' else (0, 1 if di>0 else -1)
        segs.append((i,j,sx,sy,L,c))
    # two passes to avoid cross-interference
    painted=set(); erased=set()
    for (i,j,sx,sy,L,c) in segs:
        for k in range(1,L):
            p,q=i+sx*k,j+sy*k
            if (p,q) in erased: continue
            if any(i2+si2*(k-k)==p and j2+sij*(k-k)==q for i2,_,(si2,sij),L2,_ in segs):
                pass
        # mark cells that are claimed by >=2 beams, using occ computed next
    # compute occupancy with only strict straight-line claims (no stopping)
    occ={}
    for (i,j,sx,sy,L,c) in segs:
        for k in range(1,L):
            occ.setdefault((i+sx*k,j+sy*k),[]).append((c,sx,sy,i,j))
    res=[[0]*W for _ in range(H)]
    # paint each beam; crossings = cell claimed by >=2
    stop=set()
    for (p,q),cl in occ.items():
        if len(cl)>=2:
            for c,sx,sy,i,j in cl:
                for kk in range(k:=0+1, L):
                    np_,nq=i+sx*kk,j+sy*kk
                    if (np_,nq)!=(p,q): stop.add((np_,nq))
            res[p][q]=4
        else:
            c,sx,sy,i,j=cl[0]
            for kk in range(1, L):
                np_,nq=i+sx*kk,j+sy*kk
                if (np_,nq) in stop: break
                res[np_][nq]=5
    for (i,j,c) in pts:
        di,dj=VECS[c]
        ni,nj=i+di,j+dj
        if 0<=ni<H and 0<=nj<W and I[ni][nj]==0: res[ni][nj]=c
    return [[O[r][c] if O[r][c] else res[r][c] for c in range(W)] for r in range(H)]

