        for (p,q) in path: cellbeams[(p,q)].append(idx)
    cross=set(cp for cp in cellbeams if len(cellbeams[cp])>=2)
    for path,c,a in segs:
        for (p,q) in path:
            if (p,q) in cross or I[p][q]==c: continue
            O[p][q]=5
    for cp in sorted(cross, reverse=True):
        O[cp[0]][cp[1]]=4
        k=1
        while True:
            pp,qq=cp[0]+k,cp[1]-k
            if not(0<=pp<H and 0<=qq<W) or I[pp][qq]!=0: break
            O[pp][qq]=4; k+=1
    for (i,j,c) in pts:
        di,dj=offs[c]; ni,nj=i+di,j+dj
        if 0<=ni<H and 0<=nj<W: O[ni][nj]=c
    return O

